        if (!request_.commandList || !input_ || !hasViewport_ || !hasScissor_)
            throw std::runtime_error("Set Leia command list, SBS texture, viewport and scissor before weave");
        titan::Snapshot snapshot{};
        const bool usable = state_->alive.load() && state_->client->SnapshotForWeave(snapshot);
